ALTER TABLE public.international_payments ADD COLUMN customer_name text, ADD COLUMN customer_email text, ADD COLUMN checkout_session_id uuid REFERENCES public.checkout_sessions(id);
CREATE INDEX international_checkout_session ON public.international_payments(checkout_session_id);
CREATE OR REPLACE FUNCTION public.get_checkout_operation_currency(p_hours integer DEFAULT 24, p_resource uuid DEFAULT NULL, p_currency text DEFAULT 'MZN') RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$
WITH base AS (
SELECT s.id,s.created_at,s.last_seen_at,s.started_at,s.completed_at,s.attempted_at,s.error_at,s.source,s.campaign,s.device,COALESCE(s.product_id,s.payment_link_id) resource_id,COALESCE(p.name,l.title,'Checkout') resource_name,
(EXISTS(SELECT 1 FROM public.transactions t WHERE t.user_id=auth.uid() AND p_currency='MZN' AND t.metadata->'tracking'->>'operation_session_id'=s.id::text AND NOT t.is_test AND t.status='paid') OR EXISTS(SELECT 1 FROM public.international_payments t WHERE t.user_id=auth.uid() AND t.currency=p_currency AND t.checkout_session_id=s.id AND t.status='paid')) paid,
(EXISTS(SELECT 1 FROM public.transactions t WHERE t.user_id=auth.uid() AND p_currency='MZN' AND t.metadata->'tracking'->>'operation_session_id'=s.id::text AND NOT t.is_test AND t.status='failed') OR EXISTS(SELECT 1 FROM public.international_payments t WHERE t.user_id=auth.uid() AND t.currency=p_currency AND t.checkout_session_id=s.id AND t.status='failed')) failed,
(EXISTS(SELECT 1 FROM public.transactions t WHERE t.user_id=auth.uid() AND p_currency='MZN' AND t.metadata->'tracking'->>'operation_session_id'=s.id::text AND NOT t.is_test AND t.status='pending') OR EXISTS(SELECT 1 FROM public.international_payments t WHERE t.user_id=auth.uid() AND t.currency=p_currency AND t.checkout_session_id=s.id AND t.status='pending')) pending
FROM public.checkout_sessions s LEFT JOIN public.products p ON p.id=s.product_id LEFT JOIN public.payment_links l ON l.id=s.payment_link_id WHERE s.user_id=auth.uid() AND s.created_at>=now()-make_interval(hours=>LEAST(GREATEST(p_hours,1),720)) AND COALESCE(p.currency,'MZN')=p_currency AND (p_resource IS NULL OR COALESCE(s.product_id,s.payment_link_id)=p_resource)
), totals AS (SELECT count(*) visits,count(*) FILTER(WHERE started_at IS NOT NULL) started,count(*) FILTER(WHERE completed_at IS NOT NULL) completed,count(*) FILTER(WHERE attempted_at IS NOT NULL) attempted,count(*) FILTER(WHERE paid) paid,count(*) FILTER(WHERE failed AND NOT paid) failed,count(*) FILTER(WHERE pending AND NOT paid) pending,count(*) FILTER(WHERE error_at IS NOT NULL) errors,count(*) FILTER(WHERE started_at IS NOT NULL AND attempted_at IS NULL AND last_seen_at<now()-interval '30 minutes') abandoned,count(*) FILTER(WHERE last_seen_at>=now()-interval '5 minutes') active FROM base), hours AS (SELECT h.ts,count(b.id) leads,count(b.id) FILTER(WHERE b.completed_at IS NOT NULL) completed,count(b.id) FILTER(WHERE b.paid) paid FROM generate_series(date_trunc('hour',now())-interval '23 hours',date_trunc('hour',now()),interval '1 hour') h(ts) LEFT JOIN base b ON b.created_at>=h.ts AND b.created_at<h.ts+interval '1 hour' GROUP BY h.ts ORDER BY h.ts), sources AS (SELECT source,count(*) leads,count(*) FILTER(WHERE paid) paid FROM base GROUP BY source ORDER BY count(*) DESC LIMIT 12), resources AS (SELECT resource_id,resource_name,count(*) leads,count(*) FILTER(WHERE paid) paid FROM base GROUP BY resource_id,resource_name ORDER BY count(*) DESC), recent AS (SELECT id,resource_name,source,campaign,device,created_at,last_seen_at,CASE WHEN paid THEN 'paid' WHEN pending THEN 'pending' WHEN failed THEN 'failed' WHEN error_at IS NOT NULL THEN 'error' WHEN attempted_at IS NOT NULL THEN 'attempted' WHEN completed_at IS NOT NULL THEN 'completed' WHEN started_at IS NOT NULL THEN 'started' ELSE 'visited' END stage FROM base ORDER BY last_seen_at DESC LIMIT 30)
SELECT jsonb_build_object('totals',(SELECT to_jsonb(totals) FROM totals),'hourly',COALESCE((SELECT jsonb_agg(hours) FROM hours),'[]'::jsonb),'sources',COALESCE((SELECT jsonb_agg(sources) FROM sources),'[]'::jsonb),'resources',COALESCE((SELECT jsonb_agg(resources) FROM resources),'[]'::jsonb),'recent',COALESCE((SELECT jsonb_agg(recent) FROM recent),'[]'::jsonb),'updated_at',now()); $$;
REVOKE ALL ON FUNCTION public.get_checkout_operation_currency(integer,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_checkout_operation_currency(integer,uuid,text) TO authenticated;